import numpy as np

def feature(item, bins, capacity):
    """For large items, the fraction of the bin's remaining room consumed in the dominant resource."""
    large = (item[0] >= 0.4 * capacity[0]) or (item[1] >= 0.4 * capacity[1])
    if not large:
        return np.zeros(bins.shape[0])
    frac_cpu = item[0] / (bins[:, 0] + 1e-9)
    frac_mem = item[1] / (bins[:, 1] + 1e-9)
    vals = np.maximum(frac_cpu, frac_mem)
    return np.clip(vals, 0.0, 1.0)
